#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <stdatomic.h>

#define MAX_JOBS 64
#define CB_THRESHOLD 5
#define CB_TIMEOUT_SEC 3

typedef enum { CB_CLOSED, CB_OPEN, CB_HALF_OPEN } cb_state_t;

typedef struct {
    atomic_int failure_count;
    atomic_int state;
    time_t last_failure_time;
    pthread_mutex_t lock;
} circuit_breaker_t;

typedef struct job {
    int id;
    char *payload;
    size_t payload_len;
    int retries;
    struct job *next;
} job_t;

typedef struct {
    job_t *head;
    job_t *tail;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int shutdown;
    circuit_breaker_t cb;
} job_queue_t;

static job_queue_t g_queue;

void cb_init(circuit_breaker_t *cb) {
    atomic_store(&cb->failure_count, 0);
    atomic_store(&cb->state, CB_CLOSED);
    cb->last_failure_time = 0;
    pthread_mutex_init(&cb->lock, NULL);
}

int cb_allow_request(circuit_breaker_t *cb) {
    int state = atomic_load(&cb->state);
    if (state == CB_CLOSED) return 1;
    if (state == CB_OPEN) {
        pthread_mutex_lock(&cb->lock);
        time_t now = time(NULL);
        if (difftime(now, cb->last_failure_time) >= CB_TIMEOUT_SEC) {
            atomic_store(&cb->state, CB_HALF_OPEN);
            pthread_mutex_unlock(&cb->lock);
            return 1;
        }
        pthread_mutex_unlock(&cb->lock);
        return 0;
    }
    return 1; /* HALF_OPEN: allow one probe */
}

void cb_record_success(circuit_breaker_t *cb) {
    atomic_store(&cb->failure_count, 0);
    atomic_store(&cb->state, CB_CLOSED);
}

void cb_record_failure(circuit_breaker_t *cb) {
    int count = atomic_fetch_add(&cb->failure_count, 1) + 1;
    if (count >= CB_THRESHOLD) {
        pthread_mutex_lock(&cb->lock);
        cb->last_failure_time = time(NULL);
        atomic_store(&cb->state, CB_OPEN);
        pthread_mutex_unlock(&cb->lock);
    }
}

void queue_init(job_queue_t *q) {
    q->head = q->tail = NULL;
    pthread_mutex_init(&q->lock, NULL);
    pthread_cond_init(&q->cond, NULL);
    q->shutdown = 0;
    cb_init(&q->cb);
}

void queue_push(job_queue_t *q, job_t *job) {
    pthread_mutex_lock(&q->lock);
    job->next = NULL;
    if (q->tail) { q->tail->next = job; q->tail = job; }
    else { q->head = q->tail = job; }
    pthread_cond_signal(&q->cond);
    pthread_mutex_unlock(&q->lock);
}

job_t *queue_pop(job_queue_t *q) {
    pthread_mutex_lock(&q->lock);
    while (!q->head && !q->shutdown)
        pthread_cond_wait(&q->cond, &q->lock);
    if (q->shutdown && !q->head) {
        pthread_mutex_unlock(&q->lock);
        return NULL;
    }
    job_t *job = q->head;
    q->head = job->next;
    if (!q->head) q->tail = NULL;
    pthread_mutex_unlock(&q->lock);
    return job;
}

int execute_job(job_t *job) {
    /* Simulate work: jobs with payload starting with 'X' fail */
    if (job->payload && job->payload_len > 0 && job->payload[0] == 'X')
        return -1;
    return 0;
}

void job_cleanup(job_t *job) {
    if (job->payload) {
        free(job->payload);
        job->payload = NULL;
    }
}

void requeue_with_backoff(job_queue_t *q, job_t *job) {
    job->retries++;
    /* Exponential backoff simulation: just re-enqueue */
    queue_push(q, job);
}

void *worker_thread(void *arg) {
    job_queue_t *q = (job_queue_t *)arg;
    while (1) {
        job_t *job = queue_pop(q);
        if (!job) break;

        if (!cb_allow_request(&q->cb)) {
            /* Circuit open: clean up and discard */
            job_cleanup(job);
            free(job);
            continue;
        }

        int result = execute_job(job);
        if (result == 0) {
            cb_record_success(&q->cb);
            job_cleanup(job);
            free(job);
        } else {
            cb_record_failure(&q->cb);
            if (job->retries < 3) {
                /* Requeue for retry - keep payload for next attempt */
                requeue_with_backoff(q, job);
            } else {
                /* Max retries: move to dead letter */
                job_cleanup(job);
                free(job);
            }
        }
    }
    return NULL;
}

void *monitor_thread(void *arg) {
    job_queue_t *q = (job_queue_t *)arg;
    while (!q->shutdown) {
        usleep(500000);
        int state = atomic_load(&q->cb.state);
        if (state == CB_OPEN) {
            /* Log circuit breaker status only - no queue manipulation */
            pthread_mutex_lock(&q->lock);
            int count = 0;
            job_t *cur = q->head;
            while (cur) {
                count++;
                cur = cur->next;
            }
            pthread_mutex_unlock(&q->lock);
            /* In production, emit metric: queued_during_open = count */
        }
    }
    return NULL;
}

int main(int argc, char **argv) {
    queue_init(&g_queue);

    pthread_t workers[2], monitor;
    for (int i = 0; i < 2; i++)
        pthread_create(&workers[i], NULL, worker_thread, &g_queue);
    pthread_create(&monitor, NULL, monitor_thread, &g_queue);

    /* Submit jobs */
    for (int i = 0; i < 20; i++) {
        job_t *j = calloc(1, sizeof(job_t));
        if (!j) {
            fprintf(stderr, "job allocation failed\n");
            break;
        }
        j->id = i;
        j->payload = strdup(i % 3 == 0 ? "Xfail_task" : "normal_task");
        if (!j->payload) {
            fprintf(stderr, "payload allocation failed\n");
            free(j);
            break;
        }
        j->payload_len = strlen(j->payload);
        j->retries = 0;
        queue_push(&g_queue, j);
    }

    sleep(5);
    g_queue.shutdown = 1;
    pthread_cond_broadcast(&g_queue.cond);

    for (int i = 0; i < 2; i++)
        pthread_join(workers[i], NULL);
    pthread_join(monitor, NULL);

    return 0;
}
